const item = $input.first();
const jd = item.json.body?.job_description ?? '';

// Read the uploaded PDF and send it to Gemini directly (scanned PDFs work too)
const buf = await this.helpers.getBinaryDataBuffer(0, 'resume');
const pdfBase64 = buf.toString('base64');

const systemPrompt = `You are an experienced recruiter who screens candidates across all industries. Evaluate the attached resume against the job description objectively and consistently.

PROCESS
1. Identify the role's field, seniority level, and requirements from the job description. Separate must-haves (stated as required, minimum, or mandatory) from nice-to-haves (preferred, a plus, bonus).
2. For each requirement, look for concrete evidence in the resume: job titles, responsibilities, projects, tools, certifications, licenses, education, and measurable results.
3. Count equivalent evidence as a match (for example, PostgreSQL satisfies SQL, and managing a 10-person team satisfies leadership). Do not count a skill that is only implied or never shown.
4. Judge experience by relevance and recency, not just total years. For entry-level roles, count internships, academic projects, and freelance work as relevant experience.

SCORING
- Score skills, experience, and education from 0 to 100 each, then set fit_score to the weighted average: skills 50%, experience 35%, education 15%, rounded to a whole number.
- If any must-have is missing (such as a required license, degree, or minimum years of experience), list it in missing_skills and cap fit_score at 69.
- Use the full range. 90+ means the candidate meets every must-have and most nice-to-haves with strong evidence. Around 50 means roughly half the requirements are met. Do not inflate scores.
- Recommendation bands: 85-100 Strong Fit, 70-84 Good Fit, 50-69 Partial Fit, below 50 Not a Fit. The recommendation must match the band of the final fit_score.

FAIRNESS
Ignore name, age, gender, photo, marital status, religion, nationality, address, and school prestige. Judge only job-relevant qualifications.

OUTPUT
- matched_skills and missing_skills: short labels (1-4 words each) taken from the job's requirements, at most 10 each, must-haves first.
- summary: 3-4 sentences covering the strongest matches, the biggest gaps, and overall fit.
- recommendation_reason: 1-2 sentences naming the deciding factor.
- suggestions: up to 3 specific actions tied to this resume and this job (for example, "Add the PRC license number to the header"), not generic advice.
- Write in English, even if the resume or job description is in another language.
- If the attached file is not a resume, set every score to 0, set recommendation to "Not a Fit", leave the skill lists empty, and say so in the summary.`;

const userText = `JOB DESCRIPTION:\n${jd}\n\nAnalyze the attached resume against this job description.`;

const RECS = ['Strong Fit', 'Good Fit', 'Partial Fit', 'Not a Fit'];

const payload = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{
    role: 'user',
    parts: [
      { inlineData: { mimeType: 'application/pdf', data: pdfBase64 } },
      { text: userText }
    ]
  }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        fit_score: { type: 'INTEGER' },
        breakdown: {
          type: 'OBJECT',
          properties: {
            skills: { type: 'INTEGER' },
            experience: { type: 'INTEGER' },
            education: { type: 'INTEGER' }
          },
          required: ['skills', 'experience', 'education']
        },
        matched_skills: { type: 'ARRAY', items: { type: 'STRING' } },
        missing_skills: { type: 'ARRAY', items: { type: 'STRING' } },
        summary: { type: 'STRING' },
        recommendation: { type: 'STRING', enum: RECS },
        recommendation_reason: { type: 'STRING' },
        suggestions: { type: 'ARRAY', items: { type: 'STRING' } }
      },
      required: ['fit_score', 'breakdown', 'matched_skills', 'missing_skills', 'summary', 'recommendation', 'recommendation_reason', 'suggestions']
    }
  }
};

return [{ json: { payload } }];

// Handles both paths: a normal Gemini response, or an error passed through from LLM Fallback.
const resp = $input.first().json;
const cfg = $('Config').first().json;

const fail = (msg) => [{ json: { fit_score: null, error: msg } }];

if (resp.error) {
  const msg = resp.error.message || JSON.stringify(resp.error);
  return fail(`Both ${cfg.model} and ${cfg.fallback_model} failed: ${msg}`);
}

const cand = resp.candidates?.[0];
if (!cand) return fail('Gemini returned no candidates: ' + JSON.stringify(resp.promptFeedback || resp).slice(0, 300));

const raw = (cand.content?.parts || [])
  .filter(p => typeof p.text === 'string' && !p.thought)
  .map(p => p.text).join('').trim()
  .replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let r;
try { r = JSON.parse(raw); }
catch (e) { return fail(`Gemini response was not valid JSON (finishReason: ${cand.finishReason}).`); }

return [{ json: {
  fit_score: r.fit_score ?? null,
  breakdown: r.breakdown ?? {},
  matched_skills: r.matched_skills ?? [],
  missing_skills: r.missing_skills ?? [],
  summary: r.summary ?? '',
  recommendation: r.recommendation ?? '',
  recommendation_reason: r.recommendation_reason ?? '',
  suggestions: r.suggestions ?? [],
  model: resp.modelVersion || cfg.model   // the model that actually answered (primary or fallback)
} }];
